// a donut cut in half — flat cream face on the cut edge, for dividers and decor
function HalfDonut({ icing = "#FF8FAB", size = 48, className = "", flip = false }) {
  const sprinkles = [
    { x: 12, y: 13, c: "#FFC75F" },
    { x: 23, y: 18, c: "#8FE3C4" },
    { x: 16, y: 27, c: "#F9F871" },
  ];
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 40 40"
      className={`half-donut ${className}`.trim()}
      aria-hidden="true"
      style={flip ? { transform: "scaleX(-1)" } : undefined}
    >
      <path
        d="M 20 4 A 16 16 0 0 0 20 36 L 20 26.5 A 6.5 6.5 0 0 0 20 13.5 L 20 4 Z"
        fill="#C8915C"
        stroke="#3a2418"
        strokeWidth="1.2"
      />
      <path
        d="M 20 4 A 16 16 0 0 0 20 36 L 20 33 A 13 13 0 0 0 20 7 L 20 4 Z"
        fill={icing}
      />
      <rect x="17.5" y="5" width="5" height="30" rx="2.4" fill="#FFF9F0" stroke="#EBD6B4" strokeWidth="0.7" />
      <ellipse cx="21.5" cy="20" rx="1.7" ry="6.2" fill="#1B120C" opacity="0.9" />
      {sprinkles.map((s, i) => (
        <circle key={i} cx={s.x} cy={s.y} r="1.5" fill={s.c} />
      ))}
    </svg>
  );
}

